 if(beat!==finale.beat){finale.beat=beat;if($('#cityFinaleSpeaker'))$('#cityFinaleSpeaker').textContent=finaleLines[beat][0];if($('#cityFinaleLine'))$('#cityFinaleLine').textContent=finaleLines[beat][1];for(const [i,node]of [...root.querySelectorAll('.finale-beats i')].entries())node.classList.toggle('active',i<=beat);}
