function setVisible(value){wantedVisible=!!value;if(value&&!prepared){const standalone=document.documentElement.dataset.cityStandalone==='true';prepare(standalone?cityLoading:undefined).then(()=>{if(wantedVisible)setVisible(true);}).catch(error=>{if(standalone){root.hidden=false;overlay.innerHTML='<div class="shade"><div class="panel narrow"><h2>City could not finish loading</h2><p>'+esc(error.message)+'</p><button onclick="location.reload()">Reload</button></div></div>';}});return;}if(value===visible){if(!value)root.hidden=true;return;}visible=value;root.hidden=!value;audio.setActive(value);clearInput();last=0;if(value){if(!cityFrame)cityFrame=requestAnimationFrame(frame);Platdo.playGameOpenSound();scene?.resize();setScreen('title');}else{if(cityFrame)cancelAnimationFrame(cityFrame);cityFrame=0;saveNow();phoneOpen=false;root.classList.remove('city-phone-open');overlay.innerHTML='';pause(true);hud.hidden=true;}}
